def move_form_messages(apps, schema_editor):
    # Until now the contact form put the visitor's message in `notes` (the dashboard had no
    # way to edit notes), so it moves to `message` and `notes` becomes the owner's own.
    Customer = apps.get_model('customers', 'Customer')
    for customer in Customer.objects.exclude(notes__isnull=True).exclude(notes=''):
        customer.message, customer.notes = customer.notes, ''
        customer.save(update_fields=['message', 'notes'])


